// Joystick — two potentiometers and a button in one module.
//
// VERT and HORZ each divide the supply, so A0/A1 read where the stick is.
// SEL is the stick's push-button: the module pulls it high, pressing shorts it
// low. Change Horizontal/Vertical in the properties strip; press the stick to
// see the button.

void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT);
}

void loop() {
  Serial.print("x ");
  Serial.print(analogRead(A1));
  Serial.print("/1023  y ");
  Serial.print(analogRead(A0));
  Serial.print("/1023  button ");
  Serial.println(digitalRead(2) == LOW ? "pressed" : "released");
  delay(200);
}
